        source._ingested_at as _ingested_at,
        source._batch_id as _batch_id,
        'tpch_erp' as _source_system,
        MD5(COALESCE(CAST(source.ps_partkey AS TEXT), '') || '|' || COALESCE(CAST(source.ps_suppkey AS TEXT), '') || '|' || COALESCE(CAST(source.ps_availqty AS TEXT), '') || '|' || COALESCE(CAST(source.ps_supplycost AS TEXT), '') || '|' || COALESCE(CAST(source.ps_comment AS TEXT), '')) as _record_hash
    from source

)

